using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using MapSharedProps.EditorTools;
public static class NatureAuditChecks {
 [Serializable]class Check{public string name,detail;public bool pass;}[Serializable]class Report{public bool pass;public int checks;public string gpu;public List<Check> results;}
 static List<Check> checks=new List<Check>();static string Arg(string k){var a=Environment.GetCommandLineArgs();return a[Array.IndexOf(a,k)+1];}static void Verify(string n,bool ok,string detail=""){checks.Add(new Check{name=n,pass=ok,detail=detail});if(!ok)throw new Exception(n+": "+detail);}
 public static void Run(){int code=0;var output=Arg("-nature-output");Directory.CreateDirectory(output);try{
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var rd=ScriptableObject.CreateInstance<UniversalRendererData>();var rp=UniversalRenderPipelineAsset.Create(rd);rp.shadowDistance=30;var so=new SerializedObject(rp);so.FindProperty("m_MainLightShadowsSupported").boolValue=true;so.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=new Color(.35f,.35f,.35f);var sun=new GameObject("Audit Sun").AddComponent<Light>();sun.type=LightType.Directional;sun.intensity=2.1f;sun.shadows=LightShadows.Hard;sun.transform.rotation=Quaternion.LookRotation(new Vector3(-5,-9,-4));var floor=GameObject.CreatePrimitive(PrimitiveType.Plane);floor.transform.localScale=Vector3.one*3;var fm=new Material(Shader.Find("Universal Render Pipeline/Lit"));fm.color=new Color(.22f,.17f,.11f);floor.GetComponent<Renderer>().sharedMaterial=fm;
  var camera=new GameObject("Nature audit camera").AddComponent<Camera>();camera.gameObject.AddComponent<UniversalAdditionalCameraData>();camera.fieldOfView=50;camera.aspect=1.25f;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;var rt=new RenderTexture(1000,800,24,RenderTextureFormat.ARGB32);camera.targetTexture=rt;
  bool single=Array.IndexOf(Environment.GetCommandLineArgs(),"-nature-single")>=0;foreach(var stage in single?new[]{"current"}:new[]{"before","after"}){var source=single?Arg("-nature-source"):Path.Combine(Arg("-nature-source"),stage+"-export");var library=MapSharedPropsBuilder.ReadLibrary(Path.Combine(source,"shared_props.json"));var built=MapSharedPropsBuilder.Build(source);Verify(stage+" supported and external placements are explicit",built.placed==(single?36:39)&&built.skipped==(single?9:27),"placed="+built.placed+", skipped="+built.skipped);foreach(Transform child in built.root.transform)child.gameObject.SetActive(false);
   foreach(var id in single?Arg("-nature-ids").Split(','):new[]{"log","stump","driftwood","mushroom","shelfshroom","groundlitter","drysoil_curl","drysoil_cup","drysoil_flake","reed","fern","rootfan"}){var asset=Array.Find(library.assets,a=>a.id==id);var prefab=built.prefabs[id];var mesh=prefab.GetComponent<MeshFilter>().sharedMesh;var p=mesh.vertices;var n=mesh.normals;var uv=mesh.uv;float error=0;for(int i=0;i<p.Length;i++){error=Mathf.Max(error,Vector3.Distance(p[i],new Vector3(asset.positions[i*3],asset.positions[i*3+1],asset.positions[i*3+2])),Vector3.Distance(n[i],new Vector3(asset.normals[i*3],asset.normals[i*3+1],asset.normals[i*3+2])),Vector2.Distance(uv[i],new Vector2(asset.uv[i*2],asset.uv[i*2+1])));}Verify(stage+" "+id+" exact source position normal UV and triangle count",error<.000001f&&mesh.triangles.Length==asset.triangles.Length,"max="+error+", meshRuntimeBytes="+UnityEngine.Profiling.Profiler.GetRuntimeMemorySizeLong(mesh));var renderer=prefab.GetComponent<Renderer>();Verify(stage+" "+id+" persistent one material without shader errors",AssetDatabase.Contains(mesh)&&renderer.sharedMaterials.Length==1&&!ShaderUtil.ShaderHasError(renderer.sharedMaterial.shader));
    var o=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var bounds=mesh.bounds;float d=Mathf.Max(.2f,bounds.size.magnitude*1.8f),target=bounds.max.y*.45f;foreach(var view in new[]{"near","back","top"}){camera.transform.position=view=="top"?new Vector3(0,d,0):new Vector3(d*.6f*(view=="back"?-1:1),target+d*.35f,-d*.8f*(view=="back"?-1:1));camera.transform.rotation=Quaternion.LookRotation(new Vector3(0,target,0)-camera.transform.position,view=="top"?Vector3.forward:Vector3.up);camera.nearClipPlane=.002f;camera.Render();RenderTexture.active=rt;var png=new Texture2D(1000,800,TextureFormat.RGB24,false);png.ReadPixels(new Rect(0,0,1000,800),0,0);png.Apply();File.WriteAllBytes(Path.Combine(output,stage+"-"+id+"-"+view+".png"),png.EncodeToPNG());UnityEngine.Object.DestroyImmediate(png);RenderTexture.active=null;}UnityEngine.Object.DestroyImmediate(o);
   }
   if(!single){var shell=built.root.transform.Find("night-shells-0");Verify(stage+" shells retains the formal nine-part grounded output",shell!=null&&shell.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3==220);}built.root.SetActive(false);
  }Verify("actual D3D11 Native renders completed",SystemInfo.graphicsDeviceType==GraphicsDeviceType.Direct3D11);
 }catch(Exception e){checks.Add(new Check{name="exception",detail=e.ToString(),pass=false});Debug.LogException(e);code=1;}finally{File.WriteAllText(Path.Combine(output,"report.json"),JsonUtility.ToJson(new Report{pass=code==0,checks=checks.Count,gpu=SystemInfo.graphicsDeviceName,results=checks},true));EditorApplication.Exit(code);}}
}
